UPDATE questions SET
  choices = $EXPL$["Expensed as incurred because training costs are never capitalizable","Capitalized as an implementation cost during the application development stage","Deferred until the system go-live date and then amortized over its life","Offset against subscription fees to reduce the net hosting arrangement cost"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (A): Under ASU 2018-15 and ASC 350-40, training costs are always expensed as incurred regardless of when they occur during the project lifecycle. Training does not contribute to the development or configuration of the software and therefore does not qualify for capitalization.
Wrong (B): Training costs are explicitly excluded from capitalizable implementation costs, even when incurred during the application development stage.
Wrong (C): Deferring training costs is not permitted; they must be expensed when incurred, not accumulated for later amortization.
Wrong (D): Training costs cannot be offset against subscription fees; they are a separate expense recognized in the period incurred.$EXPL$
WHERE id = 3383;
